  assert.equal(dispatch({...book, id:"next-day", day:"2025-04-03", units:8}).status, "booked");
  assert.equal(dispatch({...book, id:"other", tenant:"iris", units:5}).status, "booked");
  assert.equal(dispatch({...book, id:"other-full", tenant:"iris", units:1}).status, "full");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "cancelled");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "replay");
  assert.equal(dispatch(book).status, "cancelled");
  assert.equal(dispatch({...book, id:"replacement"}).status, "booked");
  assert.deepEqual(dispatch({...base, action:"usage"}), {units:8});
