  assert.equal(dispatch({...renewal, id:"full", units:2}).status, "full");
  dispatch({service:"studio", action:"cancel", id:"renewed"});
  assert.equal(dispatch(renewal).status, "cancelled");
  dispatch({service:"studio", action:"cancel", id:"original"});
  assert.equal(dispatch({...renewal, id:"missing"}).status, "missing");
  dispatch({...base, id:"iris", tenant:"iris", units:5});
  assert.equal(dispatch({...renewal, previous:"iris", id:"iris-full", units:6}).status, "full");
});

